#nullable enable // autogenerated

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;
using Cysharp.Threading.Tasks;
using MVZ2.Managers;
using MVZ2.Resources;
using MVZ2.Sprites;
using MVZ2Logic.Resources;
using Newtonsoft.Json;
using NGettext;
using PVZEngine;
using PVZEngine.Tools.Unity;
using UnityEngine;

namespace MVZ2.Localization
{
    public class ResourcePackReaderDirectoryV1 : ResourcePackReaderV1, IResourcePackReaderDirectory
    {
        public ResourcePackReaderDirectoryV1(MainManager main) : base(main)
        {
        }
        public override async UniTask<ResourcePack?> ReadPack(string key, string path)
        {
            try
            {
                var packReadData = await UniTask.RunOnThreadPool(() => ReadPackData(key, path));
                if (packReadData == null)
                    return null;
                var pack = new ResourcePack(key);

                await UniTask.SwitchToMainThread();

                ApplyReadData(pack, packReadData, (p, n) => ReadTexture2DDirectory(p, n));

                return pack;
            }
            catch (Exception e)
            {
                Debug.LogError($"读取语言包Zip失败：{e}");
                return null;
            }
        }
        private async UniTask<PackReadData> ReadPackData(string key, string path)
        {
            // 新建一个资源包实例。
            var packData = new PackReadData(key);

            // manifest路径。
            var manifestPath = Path.Combine(path, MANIFEST_FILENAME);

            // 将manifest读取到内存。
            var manifest = await LoadManifest(manifestPath);
            if (manifest == null)
            {
                throw new FileNotFoundException($"The file {MANIFEST_FILENAME} in resource pack {path} is missing!");
            }

            // 从manifest中读取资源包内容。
            await ReadPackFromManifest(path, manifest, packData, key);
            return packData;
        }
        private async UniTask<ResourcePackManifest?> LoadManifest(string path)
        {
            // 加载Sprite Manifest文件。
            if (!File.Exists(path))
                return null;
            using var manifestStream = File.Open(path, FileMode.Open);
            using var manifestReader = new StreamReader(manifestStream);
            var manifestJson = await manifestReader.ReadToEndAsync();

            return JsonConvert.DeserializeObject<ResourcePackManifest>(manifestJson);
        }
        private async UniTask ReadPackFromManifest(string path, ResourcePackManifest manifest, PackReadData packData, string key)
        {
            // 加载翻译文件。
            await ReadPackCatalogsFromManifest(path, manifest, packData);

            // 加载贴图。
            ReadPackSpritesFromManifest(path, manifest, packData, key);
        }
        private async UniTask ReadPackCatalogsFromManifest(string path, ResourcePackManifest manifest, PackReadData packData)
        {
            if (manifest.localization == null)
                return;

            if (manifest.localization.languages != null)
            {
                foreach (var language in manifest.localization.languages)
                {
                    // 语言代码。
                    var code = language.code;
                    if (string.IsNullOrEmpty(code))
                        continue;

                    var catalogDictionary = new Dictionary<string, Catalog>();
                    if (language.catalogs != null)
                    {
                        foreach (var relativePath in language.catalogs)
                        {
                            // 获取catalog的路径，并加载。
                            var catalogPath = Path.Combine(path, "assets", relativePath);
                            var catalog = await LoadPackMOFileDirectory(catalogPath, code);

                            // 将加载后的catalog注册。
                            var filenameWithoutExt = Path.GetFileNameWithoutExtension(catalogPath);
                            catalogDictionary.Add(filenameWithoutExt, catalog);
                        }
                    }
                    packData.catalogs.Add(code, catalogDictionary);
                }
            }
        }
        private async UniTask<Catalog> LoadPackMOFileDirectory(string moFile, string lang)
        {
            using (var stream = File.Open(moFile, FileMode.Open))
            {
                using (MemoryStream memory = new MemoryStream())
                {
                    await stream.CopyToAsync(memory);
                    memory.Seek(0, SeekOrigin.Begin);
                    return new Catalog(memory, new CultureInfo(lang));
                }
            }
        }
        private void ReadPackSpritesFromManifest(string path, ResourcePackManifest manifest, PackReadData pack, string key)
        {
            // 加载贴图
            if (manifest.textures == null)
                return;

            var generatedCategory = GetLanguagePackSpriteCategory(key);

            foreach (var packTexture in manifest.textures)
            {
                if (string.IsNullOrEmpty(packTexture.texture))
                    continue;

                if (string.IsNullOrEmpty(packTexture.key))
                {
                    Log.LogWarning($"Missing resource pack texture key {packTexture.texture}.");
                    continue;
                }

                // 获取贴图路径。
                var texturePath = Path.Combine(path, "assets", packTexture.texture).Replace("\\", "/");
                var textureID = NamespaceID.Parse(packTexture.key, Main.BuiltinNamespace);

                // 获取ID和图片标签。
                var splitTexturePaths = Path.ChangeExtension(packTexture.texture, string.Empty).TrimEnd('.').Split('/', '\\');
                string nsp, textureId;
                if (splitTexturePaths.Length > 1)
                {
                    nsp = splitTexturePaths[0];
                    textureId = string.Join("/", splitTexturePaths.Skip(1));
                }
                else
                {
                    nsp = string.Empty;
                    textureId = string.Join("/", splitTexturePaths);
                }
                SpriteHelper.ParseIDAndTags(textureId, out textureId, out var tags);

                // 加载贴图。
                var textureEntry = new TextureEntry(textureID, texturePath)
                {
                    filterMode = (FilterMode)packTexture.filter
                };
                var slices = packTexture.slices;
                if (slices != null)
                {
                    for (int i = 0; i < slices.Length; i++)
                    {
                        var slice = slices[i];
                        var sliceKey = slice.key;
                        SpriteReference? spriteRef = null;
                        if (sliceKey != null && SpriteReference.TryParse(sliceKey, Main.BuiltinNamespace, out var sprRef))
                        {
                            spriteRef = sprRef;
                        }
                        if (spriteRef == null)
                        {
                            spriteRef = new SpriteReference(textureID, i);
                        }
                        var spriteKey = new SpriteLookupKey(spriteRef, slice.tags ?? tags);
                        var sliceData = new SliceData(spriteKey)
                        {
                            border = new Vector4(slice.borderLeft, slice.borderBottom, slice.borderRight, slice.borderTop),
                            extrude = 0,
                            meshType = slice.fullRect ? SpriteMeshType.FullRect : SpriteMeshType.Tight,
                            pivot = new Vector2(slice.pivotX, slice.pivotY),
                            pixelsPerUnit = 100,
                            rect = new Rect(slice.x, slice.y, slice.width, slice.height),
                            single = slice.single,
                            spriteKey = spriteKey,
                        };
                        textureEntry.slices.Add(sliceData);
                    }
                }
                pack.textureEntries.Add(textureEntry);
            }
        }
        private Texture2D? ReadTexture2DDirectory(string texturePath, string name = "texture2D")
        {
            if (!File.Exists(texturePath))
                return null;
            using var spriteStream = File.Open(texturePath, FileMode.Open);
            using var spriteMemory = new MemoryStream();
            spriteStream.CopyTo(spriteMemory);

            var bytes = spriteMemory.ToArray();
            return Main.ResourceManager.GenerateTextureFromBytes(bytes, name);
        }
    }
}
